with joined as (select e.*, d.location, d.budget from employees e inner join departments d on e.dept_id = d.id) select level, case when budget >= 3383000 then 'PREMIUM' else 'STANDARD' end as budget_tier, count(*) as event_count, round(sum(budget) / nullif(count(case when job_title = 'Engineer' then 1 end), 0), 2) as budget_per_engineer, round(avg(salary), 2) as avg_salary from joined group by level, case when budget >= 3383000 then 'PREMIUM' else 'STANDARD' end
